const ST=[['Request a Quote','Share your name and phone number with us.'],['Site Survey','Our Tata Power Solar team visits to check your roof and energy needs.'],['Installation','Trained installers fit your solar system safely at your property.'],['Cut Your Bill','Generate your own power and watch your electricity bill come down.']];
const sec=(i,x='')=>`<section class="s rv"><img data-i="${i}" src="${IMG[i]}" alt="">${x}</section>`;
const hero=sec(0,`<div class="sun" style="left:63.4%;top:17%"><i></i><i></i><i></i><u class="rays"></u><b></b></div><a class="hs" href="#" onclick="openQ();return false" style="left:6.5%;top:71.5%;width:16%;height:9%" aria-label="Free Consultation"></a>`+[8,22,35,50,63,78,90].map((l,i)=>`<i class="sk" style="left:${l}%;animation-delay:${i*1.1}s"></i>`).join(''));
