const SB=[[4.1,22,29.5,63.6],[34.9,22,29.2,63.6],[65.5,22,28.8,63.6]],XS=[67,288,511,732,953,1175];
function lift(sel,im,B,fn){document.querySelectorAll(sel).forEach(c=>{c.innerHTML='';B.forEach((b,i)=>{const[l,t,w,h]=b,e=document.createElement('div');e.className='wc';e.style.cssText=`left:${l}%;top:${t}%;width:${w}%;height:${h}%;background-image:url(${IMG[im]});background-size:${10000/w}% auto;background-position:${l/(100-w)*100}% ${t/(100-h)*100}%;animation-delay:${i*.1}s`;e.tabIndex=0;e.onclick=()=>fn(i);e.onkeydown=k=>k.key=='Enter'&&fn(i);c.appendChild(e)})})}
lift('.cards',1,XS.map(x=>[x/14.48,50.85,14.23,31.96]),i=>{$('wi').textContent=WD[i][0];$('wt').textContent=WD[i][1];$('wp').textContent=WD[i][2];$('wdlg').showModal()});
lift('.sols',2,SB,i=>{const s=SD[i],b=SB[i],t=39.1,h=27.5,g=$('sdg');g.style.cssText=`aspect-ratio:${b[2]/100*2896}/${h/100*1904};background-image:url(${IMG[2]});background-repeat:no-repeat;background-size:${10000/b[2]}% auto;background-position:${b[0]/(100-b[2])*100}% ${t/(100-h)*100}%`;$('sdt').textContent=s[0];$('sdp').textContent=s[1];$('sdl').innerHTML=s[2].map(x=>`<li>${x}</li>`).join('');$('sdlg').showModal()});
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');e.target.querySelectorAll('.wc').forEach(w=>w.classList.add('in'))}}),{threshold:.1});Q('.rv').forEach(e=>io.observe(e));
/* routing */
const KEYS=['home','why','tata','solutions','how','about'];
function route(smooth=true){const r=location.hash.replace('#/','')||'home';
 if(r=='admin'){if(!unlocked){history.replaceState(null,'','#/about');return route()}$('main').hidden=true;$('admin').hidden=false;scrollTo(0,0);tab(window._t||'dash');return}
 $('main').hidden=false;$('admin').hidden=true;const el=$('s-'+r);if(el)el.scrollIntoView({behavior:smooth?'smooth':'auto',block:'start'})}
function go(k){$('nv').classList.remove('open');history.replaceState(null,'','#/'+k);route()}
Q('nav a').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.r)});$('hb').onclick=()=>$('nv').classList.toggle('open');
addEventListener('hashchange',()=>route());
function spy(){if(!$('admin').hidden)return;let cur='home';KEYS.forEach(k=>{const e=$('s-'+k);if(e&&e.getBoundingClientRect().top<=innerHeight*.4)cur=k});Q('nav a').forEach(a=>a.classList.toggle('on',a.dataset.r==cur))}
let tk=0;const tick=()=>{if(tk)return;tk=requestAnimationFrame(()=>{tk=0;spy();glassCheck()})};addEventListener('scroll',tick,{passive:true});addEventListener('resize',tick);
const SMP=[];IMG.forEach((s,i)=>{const im=new Image();im.onload=()=>{const w=48,h=Math.round(im.height*w/im.width),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,w,h);SMP[i]={w,h,d:x.getImageData(0,0,w,h).data};glassCheck()};im.src=s});
function glassCheck(){const hd=document.querySelector('header'),band=hd.offsetHeight+6;let tot=0,n=0;Q('.s>img').forEach(im=>{const r=im.getBoundingClientRect(),S=SMP[+im.dataset.i];if(!S||r.bottom<=0||r.top>=band)return;const y0=Math.max(0,-r.top),y1=Math.min(r.height,band-r.top),a=Math.floor(y0/r.height*S.h),b=Math.max(a+1,Math.ceil(y1/r.height*S.h));for(let y=a;y<b&&y<S.h;y++)for(let x=0;x<S.w;x++){const k=(y*S.w+x)*4,R=S.d[k],G=S.d[k+1],B=S.d[k+2],lum=(.299*R+.587*G+.114*B)/255;tot+=(1-lum)+(Math.max(R,G,B)-Math.min(R,G,B))/255*.6;n++}});const v=n?tot/n:0;if(v>.16)hd.classList.add('glass');else if(v<.1)hd.classList.remove('glass')}
addEventListener('load',()=>{route(false);spy();init()});
/* quotation */
function openQ(){$('fm').textContent='';$('ok').hidden=true;$('qf').hidden=false;$('ph').hidden=false;dlg.showModal()}
$('wq').onclick=()=>{$('wdlg').close();openQ()};
const CFG={wa:'',email:'',endpoint:''},ENC=encodeURIComponent;
let supabaseClient = null;
async function deliver(kind,data,msg){
 if(db){try{await db.collection(kind=='quote'?'quotes':'submissions').doc((kind=='quote'?'q':'s')+data.at+Math.random().toString(36).slice(2,5)).set(data);return{via:'db'}}catch(e){}}
 if(CFG.endpoint){try{await fetch(CFG.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({kind,...data})});return{via:'endpoint'}}catch(e){}}
 if(CFG.wa){const l=`https://wa.me/${CFG.wa.replace(/\D/g,'')}?text=${ENC(msg)}`;window.open(l,'_blank','noopener');return{via:'link',link:l,label:'Open WhatsApp'}}
 if(CFG.email){const l=`mailto:${CFG.email}?subject=${ENC(kind=='quote'?'Solar quotation request':'Customer review')}&body=${ENC(msg)}`;return{via:'link',link:l,label:'Open Email'}}
 return null}
$('qf').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),m=$('fm');m.textContent='';
 if(!/^\d{13}$/.test(f.consumer)){m.textContent='Consumer number must be exactly 13 digits.';return}
 f.at=Date.now();f.status='new';
 const r=await deliver('quote',f,`New solar quotation request\nName: ${f.name}\nConsumer No: ${f.consumer}\nPhone: ${f.phone}\nPlace: ${f.place}`);
 if(!r){m.textContent='Sorry, we could not send your request right now. Please try again shortly.';return}
 e.target.reset();$('qf').hidden=true;$('ph').hidden=true;$('ok').hidden=false;
 $('okp').textContent=r.via=='link'?'Almost done – press Send in the message that opened to complete your request.':'Our team will contact you shortly.';
 $('okl').innerHTML=r.link?`<a href="${esc(r.link)}" target="_blank" rel="noopener">${r.label}</a>`:'';
 if(r.via!='link')setTimeout(()=>dlg.open&&dlg.close(),3200)};
/* review form */
const TAGS=['Quick response','Professional team','On-time installation','Quality products','Value for money','Great savings'];
$('ch').innerHTML=TAGS.map(t=>`<button type="button" onclick="this.classList.toggle('on')">${t}</button>`).join('');
$('sr').innerHTML=[1,2,3,4,5].map(n=>`<span data-n="${n}">★</span>`).join('');
$('sr').onclick=e=>{const n=+e.target.dataset.n;if(!n)return;rs=n;Q('#sr span').forEach(s=>s.classList.toggle('on',+s.dataset.n<=n))};
function pickPhoto(file,cb){if(!file)return;const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const s=Math.min(i.width,i.height),c=document.createElement('canvas');c.width=c.height=160;c.getContext('2d').drawImage(i,(i.width-s)/2,(i.height-s)/2,s,s,0,0,160,160);cb(c.toDataURL('image/jpeg',.8))};i.src=r.result};r.readAsDataURL(file)}
$('rp').onchange=e=>pickPhoto(e.target.files[0],d=>{rphoto=d;$('pa').innerHTML=`<img class="av" src="${d}" alt="">`});
function openR(){$('rm').textContent='';$('rf').hidden=false;$('rok').hidden=true;$('rf').reset();rs=0;rphoto='';$('pa').innerHTML='<span class="av">+</span>';Q('#sr span,#ch button').forEach(e=>e.classList.remove('on'));$('rdlg').showModal()}
$('rf').onsubmit=async e=>{e.preventDefault();const m=$('rm');m.textContent='';const n=$('rn').value.trim();if(!n||!rs){m.textContent='Please add your name and a star rating.';return}
 const d={name:n,stars:rs,tags:[...Q('#ch button.on')].map(b=>b.textContent),text:$('rt').value.trim().slice(0,250),photo:rphoto,at:Date.now()};
 const r=await deliver('review',d,`New customer review\nName: ${d.name}\nRating: ${d.stars}/5\nLiked: ${d.tags.join(', ')||'-'}\nComment: ${d.text||'-'}`);
 if(!r){m.textContent='Sorry, we could not send your review right now. Please try again shortly.';return}
 $('rf').hidden=true;$('rok').hidden=false;$('rokp').textContent=r.via=='link'?'Almost done – press Send in the message that opened to share your review.':'Your review will appear on the site once approved.';$('rokl').innerHTML=r.link?`<a href="${esc(r.link)}" target="_blank" rel="noopener">${r.label}</a>`:'';
 if(r.via!='link')setTimeout(()=>$('rdlg').open&&$('rdlg').close(),3500)};
const av=r=>r.photo?`<img class="av" src="${esc(r.photo)}" alt="">`:`<span class="av">${esc((r.name||'?')[0].toUpperCase())}</span>`;
const stars=n=>'★'.repeat(n)+'☆'.repeat(5-n);
const tags=r=>(r.tags&&r.tags.length)?`<div class="tg">${r.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:'';
const rcard=r=>`<div class="rc"><div class="rh">${av(r)}<div><b>${esc(r.name)}</b><div class="stars">${stars(r.stars)}</div></div></div>${tags(r)}${r.text?`<p>${esc(r.text)}</p>`:''}</div>`;
/* admin */
function askPw(){
  $('pe').textContent='';
  $('pw').value='';
  $('pdlg').showModal();
  setTimeout(()=>$('pw').focus(),50)
}
$('pf').onsubmit=async e=>{
  e.preventDefault();
  const email = ($('admin-email')?.value || '').trim();
  const password = $('pw').value;
  if(!supabaseClient){
    $('pe').textContent='Supabase is not configured.';
    return;
  }
  try{
    const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});
    if(error)throw error;
    unlocked=!!data.session;
    $('pdlg').close();
    go('admin');
  }catch(err){
    console.error(err);
    $('pe').textContent=err.message||'Login failed.';
  }
};
async function lock(){
  try{if(supabaseClient) await supabaseClient.auth.signOut()}catch(e){}
  unlocked=false;
  go('about')
}
function tab(n){window._t=n;Q('.tp').forEach(e=>e.classList.toggle('on',e.id=='t-'+n));Q('.tabs button').forEach(e=>e.classList.toggle('on',e.dataset.tb==n))}
Q('.tabs button').forEach(b=>b.onclick=()=>tab(b.dataset.tb));
const ms=(id,t)=>{const e=$(id);e.textContent=t;setTimeout(()=>e.textContent='',3000)};
async function savePw(){
  ms('m-sec','Admin passwords are managed in Supabase Authentication. Create/change the admin user there.');
}
const gd=ts=>new Date(ts).toLocaleString();
async function upd(c,id,p){
  try{
    if(!supabaseClient)throw new Error('Supabase is not configured.');
    const {error}=await supabaseClient.from(c).update(p).eq('id',id);
    if(error)throw error;
  }catch(e){
    console.error(e);
    alert('Could not save: '+(e.message||'Database error'));
  }
}
async function del(c,id){
  if(!confirm('Delete this entry?'))return;
  try{
    if(!supabaseClient)throw new Error('Supabase is not configured.');
    const {error}=await supabaseClient.from(c).delete().eq('id',id);
    if(error)throw error;
    if(c==='quotes'){
      QS=QS.filter(x=>x.id!==id); rq(); dash();
    }else if(c==='reviews'){
      RS=RS.filter(x=>x.id!==id); rr(); dash();
    }else if(c==='submissions'){
      SU=SU.filter(x=>x.id!==id); rr(); dash();
    }
  }catch(e){
    console.error('Delete failed',e);
    alert('Could not delete: '+(e.message||'Database error'));
  }
}
function rq(){const s=$('qf1').value.toLowerCase(),f=$('qf2').value;$('ql').innerHTML=QS.filter(q=>(!f||(q.status||'new')==f)&&[q.name,q.phone,q.place,q.consumer].join(' ').toLowerCase().includes(s)).map(q=>`<tr><td>${gd(q.at)}</td><td>${esc(q.name)}</td><td>${esc(q.consumer)}</td><td><a href="tel:${esc(q.phone)}">${esc(q.phone)}</a></td><td>${esc(q.place)}</td><td><select onchange="upd('quotes','${q.id}',{status:this.value})">${['new','contacted','closed'].map(o=>`<option${(q.status||'new')==o?' selected':''}>${o}</option>`).join('')}</select></td><td><input value="${esc(q.note)}" onchange="upd('quotes','${q.id}',{note:this.value})"></td><td><button class="dl" onclick="del('quotes','${q.id}')">✕</button></td></tr>`).join('')||'<tr><td colspan="8">No requests.</td></tr>'}
function dash(){const d=new Date().toDateString();$('kp').innerHTML=[[QS.length,'Total requests'],[QS.filter(q=>(q.status||'new')=='new').length,'New requests'],[QS.filter(q=>new Date(q.at).toDateString()==d).length,'Today'],[SU.length,'Reviews awaiting approval'],[RS.filter(r=>!r.hide).length,'Reviews published']].map(k=>`<div><b>${k[0]}</b>${k[1]}</div>`).join('')}
async function approve(id){const s=SU.find(x=>x.id==id);if(!s)return;try{const{id:_,...d}=s;const {error:e1}=await supabaseClient.from('reviews').upsert({id:'r'+s.at,...d,hide:false});
    if(e1)throw e1;
    const {error:e2}=await supabaseClient.from('submissions').delete().eq('id',id);
    if(e2)throw e2;}catch(e){alert('Could not approve – needs edit access')}}
function rr(){$('pn').innerHTML=SU.map(r=>`<div class="card">${av(r)}<div class="f"><b>${esc(r.name)}</b> <span class="stars">${stars(r.stars)}</span>${tags(r)}<p style="margin:4px 0;font-size:14px">${esc(r.text)}</p></div><div><button class="ab" onclick="approve('${r.id}')">Approve</button> <button class="dl" onclick="del('submissions','${r.id}')">Reject</button></div></div>`).join('')||'<p style="color:var(--mut)">No reviews waiting.</p>';
 $('pb').innerHTML=RS.map(r=>`<div class="card">${av(r)}<div class="f"><input id="n_${r.id}" value="${esc(r.name)}"><input id="s_${r.id}" type="number" min="1" max="5" value="${r.stars}" style="width:80px"><textarea id="t_${r.id}" rows="2">${esc(r.text)}</textarea>${tags(r)}<label style="font-size:13px"><input type="checkbox" id="h_${r.id}" style="width:auto"${r.hide?'':' checked'}> Show on website</label> <input type="file" accept="image/*" onchange="newPhoto('${r.id}',this)" style="font-size:12px;border:0"></div><div><button class="ab" onclick="rsave('${r.id}')">Save</button> <button class="dl" onclick="del('reviews','${r.id}')">Delete</button></div></div>`).join('')||'<p style="color:var(--mut)">None yet.</p>';
 const v=RS.filter(r=>!r.hide);$('rl').innerHTML=v.length?v.map(rcard).join(''):'<p style="grid-column:1/-1;text-align:center;color:var(--mut)">Be the first to share your experience!</p>'}
const rsave=id=>upd('reviews',id,{name:$('n_'+id).value.trim(),text:$('t_'+id).value.trim(),stars:Math.min(5,Math.max(1,+$('s_'+id).value||5)),hide:!$('h_'+id).checked});
const newPhoto=(id,el)=>pickPhoto(el.files[0],d=>upd('reviews',id,{photo:d}));
let mp='';$('mf').onchange=e=>pickPhoto(e.target.files[0],d=>{mp=d;$('mpv').innerHTML=`<img class="av" src="${d}" alt="">`});
async function addRev(){const n=$('mn').value.trim();if(!db||!n)return;const at=Date.now();try{const {error}=await supabaseClient.from('reviews').insert({id:'r'+at,name:n,stars:Math.min(5,Math.max(1,+$('ms').value||5)),text:$('mt').value.trim(),tags:[],photo:mp,at,hide:false});
    if(error)throw error;$('mn').value=$('mt').value='';mp='';$('mpv').innerHTML=''}catch(e){alert('Could not save – needs edit access')}}
async function csv(){const q=s=>'"'+String(s??'').replace(/"/g,'""')+'"';const d=[['Date','Name','Consumer No','Phone','Place','Status','Note'].map(q).join(','),...QS.map(x=>[gd(x.at),x.name,x.consumer,x.phone,x.place,x.status||'new',x.note].map(q).join(','))].join('\n');try{const dl=null;await dl.save({filename:'quotations.csv',data:d})}catch(e){}}
async function init(){try{const d=null;if(!d)return;db=d;
 db.doc('site/config').onSnapshot(s=>{cfg=s.data()||{}});
 db.collection('reviews').onSnapshot(s=>{RS=s.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>b.at-a.at);rr();dash()});
 db.collection('submissions').onSnapshot(s=>{SU=s.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>a.at-b.at);rr();dash()},()=>{});
 db.collection('quotes').onSnapshot(s=>{QS=s.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>b.at-a.at);rq();dash()},()=>{})}catch(e){}}
rr();
